#!/usr/bin/env python3
"""Sum generated bytes per region kind / operation name from a JIT artifact code-map.

Usage: scripts/dev/template_region_sizes.py <artifact-dir> [top]
"""
import collections
import json
import sys

art = sys.argv[1]
top = int(sys.argv[2]) if len(sys.argv) > 2 else 25
m = json.load(open(f"{art}/code-map.json"))
by_kind = collections.Counter()
by_op = collections.Counter()
op_count = collections.Counter()
covered = 0
for r in m["regions"]:
    size = r["endOffset"] - r["startOffset"]
    covered += size
    by_kind[r["kind"]] += size
    if r["kind"] == "instruction":
        name = r["operation"].split(" ")[0]
        by_op[name] += size
        op_count[name] += 1
end = m["runtimeAddressRange"]
total = int(end["endExclusive"], 16) - int(end["start"], 16)
print(f"total={total} covered={covered}")
for k, v in by_kind.most_common(top):
    print(f"  kind {k:32s} {v:9d} {100*v/total:5.1f}%")
for k, v in by_op.most_common(top):
    print(f"  op   {k:32s} {v:9d} n={op_count[k]:5d} avg={v/op_count[k]:7.1f}")
